bc25694a6faa13eb75622e88058e480d33b75c3fb251f932f5f4ac91"],"refs":["4ed82a885b546b47f3e65cd1","d154d49813c1c139c07d8b21"],"rows":[{"citation_id":"4ed82a885b546b47f3e65cd1","conditions":"SN 2014J E(B-V)true (reddening component)；mag, linear, reported result；CSMD model (combined F99 reddening and CSM scattering), RV=2.57, p=-2.57","error":"","error_components":[],"id":"measurement-108a47ccbc25694a6faa13eb75622e88058e480d33b75c3fb251f932f5f4ac91","limit":"none","method":"CSMD model (combined F99 reddening and CSM scattering), RV=2.57, p=-2.57","original":"0.45","original_unit":"mag","property":"视线E(B−V)消光","property_id":"prop-dot-r69b04-nt-sn-line-of-sight-ebv","representation":"linear","source":"Foley 2014","source_citation_id":"ca2798cf6b03a75c51d600f6","source_id":"work-af200983035c140946828a625e895a4a1a175e107bd0313ed44d068a2e17d7a6","source_title":"Extensive HST ultraviolet spectra and multiwavelength observations of SN 2014J in M82 indicate reddening and circumstellar scattering by typical dust","target_id":"simbad-8ed656e098d301d8b91c6c223b27f6fce65b24d06ab47955d27ecc9620bfafa5","typed":{"kind":"real","value":"0.45"},"unit":"mag","value":"0.45","year":"2014"}],"title":"Foley et al. 2014"},{"markdown":"原报 $E(B-V)=0.71\pm0.11$ mag。通过 M82 视线方向多条 DIB 等值宽度，利用银河系经验关系预测并做残差修正后取平均。反映的是气体/尘埃柱密度示踪量，不依赖 SN 光度模型。[SOURCE:work-598717e8648749996e425f28efae971421d54696f26a1c4eccf2288f76c64154:p.23]","record_ids":["measurement-1615f1b0b6be7e3944e5846225704ef722052a79509c2c848a290220e163c452"],"refs":["3d5177f3706c74d1bc2198c5","ebd91dec6ceb4c8615d2b36b"],"rows":[{"citation_id":"3d5177f3706c74d1bc2198c5","conditions":"Color excess magnitude (dimensionless in table context)；Predicted M82 E(B−V), adjusted for residuals [log W(meas) minus log W(pred)], using relationships given in Appendix Table 5.","error":"0.71±0.11","error_components":[{"kind":"symmetric_delta","level":null,"raw_text":"0.71±0.11","role":"unspecified","values":{"delta":"0.11"}}],"id":"measurement-1615f1b0b6be7e3944e5846225704ef722052a79509c2c848a290220e163c452","limit":"none","method":"Predicted M82 E(B−V), adjusted for residuals [log W(meas) minus log W(pred)], using relationships given in Appendix Table 5.","original":"0.71±0.11","original_unit":"mag","property":"视线E(B−V)消光","property_id":"prop-dot-r69b04-nt-sn-line-of-sight-ebv","representation":"linear","source":"Welty 2014","source_citation_id":"1aca060b6fe9ec55e79b346d","source_id":"work-598717e8648749996e425f28efae971421d54696f26a1c4eccf2288f76c64154","source_title":"Diffuse Interstellar Bands versus Known Atomic and Molecular Species in the Interstellar Medium of M82 toward SN 2014J","target_id":"simbad-8ed656e098d301d8b91c6c223b27f6fce65b24d06ab47955d27ecc9620bfafa5","typed":{"kind":"real","value":"0.71"},"unit":"mag","value":"0.71","year":"2014"}],"title":"Welty et al. 2014"}],"refs":["eb682033e40dc4b51f04efa7","4ed82a885b546b47f3e65cd1","3d5177f3706c74d1bc2198c5","2f893ad3b2f0dbf306e7d6f6","d154d49813c1c139c07d8b21","ebd91dec6ceb4c8615d2b36b","1600612e29a45614b15bf2af"],"title":"能否直接比较？——条件与方法对照","type":"compare"},{"id":"b5","markdown":"根据消光理论，总视向消光 $A_V$、色余 $E(B-V)$ 与消光曲线参数 $R_V$ 满足关系 $R_V = A_V / E(B-V)$ [THEORY:kb-block-08b602abd75e19e176d351164d103a05225fe648baff64b35dd1b2fb29e2a191]。该理论明确指出，$R_V$ 的数值不能在未说明环境和曲线时固定为一个普适常数；前景屏幕消光曲线与整星系衰减曲线并非同一物理对象 [THEORY:kb-block-08b602abd75e19e176d351164d103a05225fe648baff64b35dd1b2fb29e2a191]。

对 SN 2014J 的测量给出宿主星系视线方向最佳拟合色余 $E(B-V)_{\rm host} = 1.22 \pm 0.05\;{\rm mag}$，该值由 SNooPy 光变曲线拟合器在极大亮度前的测光数据上获得，误差为对称统计不确定度 [REC:measurement-02f946c04042aec0207109863e91610815a88d018bf2212fbda637b093099b39]。

以下公式与试算仅用于演示：将上述测量的中心值 $E(B-V)=1.22\;{\rm mag}$ 固定，扫描不同 $R_V$ 假设下对应的 $A_V$。此处取 $R_V=3.1$ 纯粹是演示参数，**不是** SN 2014J 的科学采用值或文献结论。试算结果不可等同于实际测量或文献采用的消光值。","refs":["7a07e105c83248ca7cfd7e14","eb682033e40dc4b51f04efa7"],"title":"知识依据与示意试算说明","type":"text"},{"id":"b6","latex":"A_V = R_V \cdot E(B-V)","refs":["7a07e105c83248ca7cfd7e14"],"title":"等价变形公式","type":"formula","variables":[{"description":"V 波段总消光","symbol":"A_V","unit":"mag","value":""},{"description":"消光曲线参数（非普适常数）","symbol":"R_V","unit":"","value":""},{"description":"色余（此处固定为测量中心值 1.22 mag）","symbol":"E(B-V)","unit":"mag","value":"1.22"}]},{"expression":"Rv*1.22","id":"b7","latex":"A_V = R_V \times 1.22","parameters":[{"choices":[],"label":"R_V（演示参数，非科学采用值）","max":5.0,"min":1.0,"name":"Rv","step":0.1,"unit":"","value":3.1}],"refs":["eb682033e40dc4b51f04efa7","7a07e105c83248ca7cfd7e14"],"title":"A_V 随 R_V 变化的示意试算","type":"explore","x":"Rv","y_label":"A_V","y_unit":"mag"}],"version":1}
